/* Pixel presentation only: never mutates battle state or consumes gameplay RNG. */
(function(root){
 'use strict';let panel,canvas,ctx,state,raf=0,last=0,signature='';
 const en=()=>root.CrawlerLocale?.language==='en',tr=(a,b)=>en()?b:a;
 const palette={red:'#df6465',blue:'#6cb5e5',yellow:'#e9c34e',purple:'#bd78ce',green:'#74cead',silver:'#d1d8df'};
 function detail(e,s){
  if(e.kind===5&&s.bloodFury)return tr('血刃阶段：攻击损血后流血+2（上限6） · 用护甲完全格挡，或治疗清1层','Blood blades: HP damage adds 2 bleed (cap 6). Fully block or heal to cleanse 1.');
  if(e.activeIn)return tr(`血影苏醒倒计时 ${e.activeIn} 回合`,`Echo activates in ${e.activeIn} turns`);
  if(e.kind===1)return e.echo?tr('血影同伴减伤10%；击败此守卫解除','Other echoes take 10% less damage; defeat this guardian'):e.wither?tr('枯萎：本回合受伤 +25%','Withered: +25% damage taken this turn'):tr(`花苞 ${e.rootBuds}/2 · 每株减伤15%；击败得1法力，清空后本回合受伤+25%`,`Buds ${e.rootBuds}/2 · 15% reduction each; kill for +1 mana; clear for +25% damage taken this turn`);
  if(e.kind===2)return e.broken?tr('已解咒 · 法术取消，护盾清空，抽1张','Seal broken · spell cancelled, shield removed, draw 1'):tr(`本回合打3色 ${e.sealProgress}/3 → 取消法术、清盾抽1 · W最多补一色 · ${e.spell==='shield'?'准备护盾':e.spell==='ink'?'准备墨咒':'准备伤害法术'}`,`Play 3 colors ${e.sealProgress}/3 → cancel spell, clear shield, draw 1 · W supplies one · ${e.spell} prepared`);
  if(e.kind===3)return tr(`疫爪附加${e.echo?1:2}层鼠疫；携药鼠清2层，治疗清1层 · ${e.echo?'血影不召鼠':`召鼠 ${e.ratSummons}/2`}`,`Claw adds ${e.echo?1:2} plague; antidote rat removes 2, healing removes 1 · ${e.echo?'echo cannot summon':`summons ${e.ratSummons}/2`}`);
  if(e.kind===4)return e.skipStrike?tr('破招成功：下次重击跳过 · 本回合破防','Interrupted: next heavy strike skipped · vulnerable this turn'):e.charging?tr(`处刑蓄力 ${e.attacks}/3 张攻击牌 · 多段仍算1张 · 下回合重击`,`Windup: ${e.attacks}/3 attack cards · multi-hit counts once · heavy strike next turn`):tr('普通攻击 → 蓄力 → 重击；蓄力回合打3张攻击破招','Attack → windup → heavy strike; play 3 attack cards during windup');
  return s.ritualUsed?tr('先击败四血影 → 血刃阶段；血影30%生命/50%攻击，依次苏醒','Defeat four echoes → blood blades; echoes: 30% HP / 50% attack, wake in sequence'):tr('护卫清空后，本牌结算结束召唤四守卫；仪式前保留1血，仅一次','When escorts fall, summon four guardians after this card; 1 HP phase gate; once only');
 }
 function ensure(){if(panel)return;panel=document.createElement('section');panel.className='boss-guide';panel.setAttribute('aria-label','Boss skills / 守关技能');document.querySelector('.battle-heading').after(panel);canvas=document.createElement('canvas');canvas.className='boss-runes';canvas.setAttribute('aria-hidden','true');canvas.width=320;canvas.height=180;document.querySelector('.arena').append(canvas);ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;}
 function render(b){ensure();state=BossRules.publicState(b);panel.hidden=!state;canvas.hidden=!state;const sig=JSON.stringify([state,en()]);if(sig!==signature){signature=sig;panel.replaceChildren();if(state){for(const e of state.bosses){const item=document.createElement('div');item.className='boss-skill kind-'+e.kind;item.dataset.boss=e.id;const title=document.createElement('strong');title.textContent=(e.echo?tr('血影 · ','Echo · '):'')+(en()?e.english:e.name);const cue=document.createElement('em');cue.className='boss-cue';cue.textContent=e.activeIn?tr('即将苏醒','AWAKENING'):[null,tr('先清花苞 → 回蓝破防','CLEAR BUDS → MANA + VULNERABILITY'),tr('本回合凑齐三色','PLAY THREE COLORS THIS TURN'),tr('留治疗，击败携药鼠','HEAL / DEFEAT ANTIDOTE RATS'),tr('蓄力时打三张攻击','THREE ATTACK CARDS DURING WINDUP'),state.bloodFury?tr('格挡血刃，及时止血','BLOCK BLADES / CLEANSE BLEED'):tr('保留资源应对四守卫','SAVE RESOURCES FOR FOUR GUARDIANS')][e.kind];item.append(cue);const description=document.createElement('span');description.textContent=detail(e,state);item.append(title,description);if(e.kind===2){const chips=document.createElement('i');chips.className='seal-chips';for(let i=0;i<3;i++){const chip=document.createElement('b');chip.style.background=palette[e.colors[i]]||(e.wildUsed&&i===e.colors.length?palette.silver:'#282334');chip.textContent=e.wildUsed&&i===e.colors.length?'W':i<e.colors.length?'◆':'◇';chips.append(chip);}item.append(chips);}panel.append(item);}const status=document.createElement('div');status.className='plague-meter';status.textContent=tr(`鼠疫 ${state.plague}/4 · 回合结束扣${state.plague}血，无视护甲，随后减1层`,`Plague ${state.plague}/4 · end turn: lose ${state.plague} HP ignoring armor, then -1 stack`);if(state.bleed)status.textContent+=tr(` · 流血 ${state.bleed}/6：回合结束扣${state.bleed}血，随后减1；治疗清1`,` · Bleed ${state.bleed}/6: lose ${state.bleed} HP at turn end, then -1; healing cleanses 1`);status.hidden=!state.plague&&!state.bleed;panel.append(status);}}
  if(state&&!raf)raf=requestAnimationFrame(frame);
 }
 function frame(now){raf=0;if(!state||document.querySelector('#combat-screen').hidden){ctx.clearRect(0,0,320,180);return;}raf=requestAnimationFrame(frame);if(document.hidden||now-last<85)return;last=now;ctx.clearRect(0,0,320,180);const a=canvas.getBoundingClientRect();if(!a.width)return;const pos=id=>{const r=document.querySelector(`[data-enemy="${id}"] .enemy-art`)?.getBoundingClientRect();return r?{x:Math.round((r.left+r.width/2-a.left)/a.width*320),y:Math.round((r.bottom-a.top)/a.height*180)}:null;};
  const motion=matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.floor(now/130);
  for(const e of state.bosses){const p=pos(e.id);if(!p)continue;ctx.strokeStyle=['','#75a159','#ac77cc','#8cbd55','#c8b995','#c35170'][e.kind];ctx.lineWidth=1;ctx.globalAlpha=.65;
   if(e.kind===1&&!e.echo)for(const h of state.helpers.filter(h=>h.kind==='root')){const q=pos(h.id);if(!q)continue;ctx.beginPath();ctx.moveTo(p.x,p.y);for(let j=1;j<=8;j++)ctx.lineTo(Math.round(p.x+(q.x-p.x)*j/8),Math.round(p.y+(q.y-p.y)*j/8+(j%2?2:-2)));ctx.stroke();}
   if(e.kind===4&&e.charging){for(let j=0;j<3-e.attacks;j++)ctx.strokeRect(p.x-12+j*8,p.y-21,6,9);}
   else{for(let j=0;j<12;j++){const t=(j+motion*.15)*Math.PI/6;ctx.fillStyle=ctx.strokeStyle;ctx.fillRect(Math.round(p.x+Math.cos(t)*18),Math.round(p.y-3+Math.sin(t)*4),2,1);}}
   if(e.kind===3){for(let j=0;j<6;j++)ctx.fillRect(p.x-12+j*5,p.y-6-((j*3+motion)%16),2,2);}
  }ctx.globalAlpha=1;
 }
 function effects(events){const b=document.querySelector('.arena')?.getBoundingClientRect();if(!b)return;for(const e of events.filter(e=>e.type==='boss_fx'&&e.fx!=='ritual').slice(-8)){const r=document.querySelector(`[data-enemy="${e.enemyId}"]`)?.getBoundingClientRect()||b;const fx={fury:'melee/claw-swipe',bleed:'melee/claw-swipe',roots:'explosions/dirt-explosion',wither:'pickups/collect-burst',seal:'ice/ice-shatter',pages:'arcane/arcane-orb',antidote:'holy/heal',plague:'water/splash',rats:'explosions/dirt-explosion',chains:'impacts/shield-block',charge:'melee/heavy-cleave',blood:'arcane/mana-burst',ritual:'explosions/plasma-explosion'}[e.fx];root.PixelVFX?.emit(fx,r.left+r.width/2,r.top+r.height*.6,{scale:.65,duration:650,bounds:b});if(e.fx==='ritual'){for(let i=0;i<4;i++)root.PixelVFX?.emit('arcane/mana-burst',b.left+b.width*(.2+i*.2),b.top+b.height*.62,{scale:.8,duration:900,bounds:b});root.PixelVFX?.shake(3);}root.GameAudio?.play(e.fx==='antidote'?'pickup':e.fx==='chains'?'block':'wand');}}

 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 async function animate(el,frames,duration){if(!el)return;const a=el.animate(frames,{duration:reduced()?80:duration,easing:'steps(12,end)',fill:'forwards'});try{await a.finished;}catch{}finally{a.cancel();}}
 function announce(text){const el=document.createElement('div');el.className='boss-announcement';el.setAttribute('role','status');el.textContent=text;document.querySelector('.arena').append(el);return el;}
 async function summon(b){
  const enemies=b.enemies.filter(e=>e.bloodEcho&&e.health>0),els=enemies.map(e=>document.querySelector(`[data-enemy="${e.id}"]`));
  els.forEach(el=>{if(el)el.style.visibility='hidden';});const banner=announce(tr('四守卫复苏 · 血影正从法阵中苏醒','FOUR GUARDIANS · Echoes rise from the ritual'));
  try{for(let i=0;i<els.length;i++){const el=els[i];if(!el?.isConnected)continue;const art=el.querySelector('.enemy-art'),r=art.getBoundingClientRect(),arena=document.querySelector('.arena'),a=arena.getBoundingClientRect(),ring=document.createElement('div');ring.className='boss-ground-seal';Object.assign(ring.style,{left:(r.left+r.width/2-a.left)+'px',top:(r.bottom-a.top-12)+'px',width:Math.max(70,r.width*.9)+'px'});arena.append(ring);
   banner.textContent=tr(`召唤 ${i+1}/4 · ${enemies[i].name}`,`Summoning ${i+1}/4 · ${enemies[i].english}`);root.GameAudio?.play('wand');await animate(ring,[{opacity:0,scale:'.2 .3'},{opacity:1,scale:'1 1'}],300);el.style.visibility='visible';
   root.PixelVFX?.emit('arcane/mana-burst',r.left+r.width/2,r.bottom-12,{scale:.5,duration:550,bounds:a});await animate(art,[{clipPath:'inset(100% 0 0 0)',translate:'0 34px',filter:'brightness(2) sepia(1)'},{clipPath:'inset(0 0 0 0)',translate:'0 0',filter:'none'}],600);ring.remove();}
  }finally{els.forEach(el=>{if(el)el.style.visibility='';});banner.remove();}
 }
 async function finale(el){
  if(!el)return;const art=el.querySelector('.enemy-art'),r=art.getBoundingClientRect(),arena=document.querySelector('.arena'),banner=announce(tr('永夜正在崩解…','THE ETERNAL NIGHT IS BREAKING…'));el.classList.add('boss-final-death');
  await animate(art,[{filter:'brightness(1)',scale:'1 1'},{filter:'brightness(3)',scale:'1.04 .96'},{filter:'brightness(7)',scale:'1.07 .93'}],1200);
  for(let i=0;i<3;i++){root.PixelVFX?.emit('explosions/plasma-explosion',r.left+r.width*(.3+i*.2),r.top+r.height*(.7-i*.2),{scale:.8+i*.15,duration:600});root.GameAudio?.play('rune');await animate(art,[{filter:'brightness(6)',opacity:1},{filter:'brightness(12)',opacity:Math.max(.1,.7-i*.25)}],300);}
  const flash=document.createElement('div');flash.className='boss-victory-flash';arena.append(flash);await animate(flash,[{opacity:0},{opacity:1,offset:.45},{opacity:1}],650);art.style.visibility='hidden';banner.remove();flash.remove();el.remove();
 }
 root.BossUI={render,effects,summon,finale};
})(globalThis);
